contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        c.lockInGuess{value: amount}(bytes32(amount));
        // wait impossible in one tx; settle requires block.number > target, so it will revert now
        bool reverted1;
        try c.settle() { reverted1 = false; } catch { reverted1 = true; }
        require(reverted1); // fresh lock cannot be settled in same block range
        assert(address(c).balance >= amount);
    }
    receive() external payable {}
}

