contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(bytes32 h) public payable {
        // On a fresh chain the target block's blockhash is zero, so the winning
        // answer is keccak256 of bytes32(0).
        require(h == keccak256(abi.encodePacked(bytes32(0))));
        require(address(this).balance >= 1 ether);
        c.lockInGuess{value: 1 ether}(h);
        uint balBefore = address(c).balance;
        c.settle();
        assert(address(c).balance == balBefore - 2 ether && address(this).balance >= 2 ether);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount) public payable {
        require(amount == 1 ether);
        require(address(this).balance >= amount);

        c.lockInGuess{value: amount}(keccak256(abi.encodePacked(uint(123))));

        // First settle (may or may not pay out, but always completes if the
        // block has advanced past the locked block; use try to be safe).
        bool reverted1;
        try c.settle() { reverted1 = false; } catch { reverted1 = true; }

        // A second settle must always revert because the guess was cleared.
        bool reverted2;
        try c.settle() { reverted2 = false; } catch { reverted2 = true; }

        assert(reverted2 && !reverted1);
    }

    receive() external payable {}
}

